class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        m, n = len(matrix), len(matrix[0])
        heap = []

        for r in range(m):
            for c in range(n):
                heappush(heap, -matrix[r][c])

                if len(heap) > k:
                    heappop(heap)
        return -heap[0]
